import { icon, escapeHtml as e } from './icons.js';
import { demoDevices, activity, appMeta } from './data.js';
const root=document.getElementById('app');
const stored=(name,def)=>{try{return JSON.parse(localStorage.getItem(name))??def}catch{return def}};
const state={route:'dashboard',device:demoDevices[0],devices:demoDevices,deviceView:'grid',filter:'all',search:'',modal:null,mobileMenu:false,
  mode:'monitor',monitor:0,app:'Excel',multi:false,fit:true,zoom:100,quality:'balanced',right:'chat',chat:[{mine:false,text:'เชื่อมต่ออุปกรณ์เรียบร้อยแล้ว (ข้อมูลตัวอย่าง)',time:'10:41'},{mine:true,text:'กำลังเปิดหน้าต่าง Excel',time:'10:42'}],files:[],
  settings:stored('krabak-prefs',{theme:'dark',quality:'balanced',clipboard:true,notifications:true,conserve:true,defaultMode:'window'}),
  backend:false,initialised:false,account:null,apiError:'',ws:null,liveSession:null,remoteStream:null,localStream:null,pc:null,rtcChannel:null,
  hostToken:null,hostCode:null,hostName:'',hostRequests:[],hostStatus:'idle',hostExpiry:null,hostChat:[],sessionEnded:false,connection:'idle',
  installPrompt:null,events:activity,
};
const now=()=>new Date().toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'});
const hasLive=()=>!!state.liveSession;
const route=()=>decodeURI((location.hash||'#/dashboard').replace(/^#\/?/,''));
const navigate=(target)=>{if(state.liveSession&&state.route==='remote'&&!target.startsWith('remote')&&target!=='login')endLive();location.hash='#/'+target;state.mobileMenu=false;if(route()===target)render();};
const btn=(label,action,style='btn',extra='')=>`<button class="${style}" data-act="${action}" ${extra}>${label}</button>`;
const tagline=(txt='กำลังแสดงข้อมูลสาธิต')=>`<span class="pill purple">${icon('spark',11)} ${e(txt)}</span>`;
const onlineStatus=(s)=>s==='online'?`<span class="pill success"><i class="status-dot"></i> ออนไลน์</span>`:`<span class="pill"><i class="status-dot offline"></i> ออฟไลน์</span>`;
const nameApp=(app)=>appMeta[app]||{icon:'file',color:'#af9fe8',title:app};
const sidebar=()=>`<aside class="sidebar ${state.mobileMenu?'mobile-open':''}" aria-label="เมนูหลัก">
  <div class="brand"><div class="brand-logo">${icon('monitor',24)}</div><div><div class="brand-head">KRABAK</div><div class="brand-sub">REMOTE MANAGER</div></div></div>
  <div class="nav-label">WORKSPACE</div>
  ${nav('dashboard','grid','ภาพรวม')}${nav('devices','monitor','อุปกรณ์ทั้งหมด',String(state.devices.length))}${nav('activity','activity','ประวัติการใช้งาน')}${nav('files','files','ไฟล์และการถ่ายโอน')}
  <div class="nav-label" style="margin-top:27px">CONNECT & MANAGE</div>
  ${nav('host','share','แชร์เครื่องนี้')}${nav('settings','settings','ตั้งค่าระบบ')}
  <div class="sidebar-bottom"><div class="sidebar-status"><div class="server-tag"><i class="dot"></i> SERVER CONFIGURATION</div><div class="server-title">Serva VPS · Ubuntu</div><div class="server-sub">aaPanel Free · ระบบต้นแบบ</div></div>
  <div class="profile"><div class="avatar">KB</div><div><strong>${e(state.account?.email?.split('@')[0]||'KRABAK Admin')}</strong><small>${state.account?'เซสชันผู้ดูแล':'โหมดสาธิต • Demo'}</small></div>${icon('dots',17)}</div></div>
</aside>`;
function nav(id,ico,text,count){let active=state.route===id?'active':'';return `<button class="nav-item ${active}" data-nav="${id}" aria-current="${active?'page':'false'}">${icon(ico,18)}<span>${text}</span>${count?`<small class="nav-count">${count}</small>`:''}</button>`}
const topbar=()=>`<header class="topbar"><div class="crumb"><button class="top-icon mobile-toggle" data-act="mobile-menu" aria-label="เปิดเมนู">${icon('menu')}</button><span class="crumb-pre">KRABAK Workspace</span><span class="crumb-pre">/</span><strong>${e(({dashboard:'ภาพรวม',devices:'อุปกรณ์',remote:'รีโมตเดสก์ท็อป',activity:'ประวัติ',files:'ไฟล์',settings:'ตั้งค่า',host:'แชร์เครื่อง'})[state.route]||'Workspace')}</strong></div>
  <div class="top-actions">${state.backend?`<span class="pill ${state.account?'success':'warning'}" style="margin-right:8px">${state.account?'เซิร์ฟเวอร์เชื่อมต่อแล้ว':'ยังไม่เข้าสู่ระบบ'}</span>`:`<span class="pill purple" style="margin-right:8px">DEMO MODE</span>`}
   <button class="top-icon" data-act="help" title="ข้อมูลระบบ">${icon('help',17)}</button><button class="top-icon" data-nav="activity" title="ประวัติ">${icon('bell',17)}</button><span class="top-divider"></span><div class="top-person"><div class="avatar">KB</div><span>${state.account?'Administrator':'ผู้ดูแลระบบ'}</span></div></div></header>`;
function render(){state.route=route().split('/')[0]||'dashboard';document.documentElement.classList.toggle('light-theme',state.settings.theme==='light');
 if(state.route==='login'){root.innerHTML=loginPage();return;}
 if(state.route==='host'){root.innerHTML=hostPage();attachHostVideo();return;}
 let content='';switch(state.route){case 'devices':content=devicesPage();break;case 'activity':content=activityPage();break;case 'files':content=filesPage();break;case 'settings':content=settingsPage();break;case 'remote':content=remotePage();break;default:content=dashboardPage();}
 root.innerHTML=`<div class="app-shell">${sidebar()}<main class="main">${topbar()}${content}</main></div>${state.modal?modalHtml():''}`;attachViewerVideo();}
const header=(eyebrow,title,sub,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="heading">${title}</h1><div class="subtitle">${sub}</div></div><div class="head-buttons">${actions}</div></div>`;
function dashboardPage(){const count=state.devices.filter(d=>d.status==='online').length;return `<div class="content">
 ${header('COMMAND CENTER','ภาพรวมการควบคุมระยะไกล','ดูสถานะคอมพิวเตอร์และเข้าถึงอุปกรณ์ของคุณได้จากทุกที่',`${btn(`${icon('share')} แชร์เครื่องนี้`,'go-host','btn')}${btn(`${icon('plus')} เชื่อมต่อเครื่องใหม่`,'connect-code','btn btn-primary')}`)}
 <section class="hero"><div class="hero-copy"><span class="hero-badge">${icon('spark',14)} ALL YOUR DEVICES, ONE WORKSPACE</span><h2>เชื่อมต่อทุกอุปกรณ์<br/>ทำงานได้อย่างไร้ขอบเขต</h2><p>สลับหลายจอ เลือกเฉพาะแอป และทำงานร่วมกันได้อย่างมีประสิทธิภาพ จากคอมพิวเตอร์หรือโทรศัพท์ของคุณ</p><div class="head-buttons">${btn(`${icon('monitor')} เปิดตัวอย่างรีโมต`,'demo-remote','btn btn-primary')}${btn(`${icon('share')} เริ่มแชร์หน้าจอจริง`,'go-host','btn')}</div></div><div class="hero-graphic"><div class="hg-monitor hg-main"><div class="hg-toolbar"><i></i><i></i><i></i></div><div class="hg-shapes"><div></div><div></div></div></div><div class="hg-monitor hg-small"><div class="hg-toolbar"><i></i><i></i></div><div class="hg-shapes"><div></div><div></div></div></div></div></section>
 <section class="stats"><div class="stat"><div class="stat-top"><div class="stat-icon">${icon('monitor')}</div><span class="stat-trend">Demo Fleet</span></div><label>อุปกรณ์ทั้งหมด</label><div class="stat-number">${state.devices.length}<small>เครื่อง</small></div></div>
 <div class="stat"><div class="stat-top"><div class="stat-icon green">${icon('wifi')}</div><span class="stat-trend">พร้อมใช้งาน</span></div><label>อุปกรณ์ออนไลน์</label><div class="stat-number">${count}<small>เครื่อง</small></div></div>
 <div class="stat"><div class="stat-top"><div class="stat-icon orange">${icon('screens')}</div><span class="stat-trend">หลายจอ</span></div><label>จอที่จำลองไว้</label><div class="stat-number">${state.devices.reduce((a,d)=>a+d.monitors.length,0)}<small>จอ</small></div></div>
 <div class="stat"><div class="stat-top"><div class="stat-icon blue">${icon('shield')}</div><span class="stat-trend">Role / Consent</span></div><label>ความปลอดภัย</label><div class="stat-number" style="font-size:24px">Ready<small>UI</small></div></div></section>
 <section class="dashboard-cols"><div class="panel"><div class="panel-pad panel-title"><div><h2>อุปกรณ์ที่ใช้ล่าสุด</h2><p>อุปกรณ์ตัวอย่างสำหรับทดสอบหน้าตาและเมนู</p></div><a class="text-link" href="#/devices">ดูทั้งหมด ${icon('chevron',13)}</a></div><div class="device-list">${state.devices.slice(0,5).map(deviceRow).join('')}</div></div>
 <div class="panel panel-pad"><div class="panel-title"><div><h2>กิจกรรมล่าสุด</h2><p>ประวัติการเชื่อมต่อและการทำงาน</p></div><a class="text-link" href="#/activity">ดูทั้งหมด ${icon('chevron',13)}</a></div>${state.events.slice(0,4).map(activityRow).join('')}<div class="help-wrap"><h4>${icon('shield',15)} การเชื่อมต่อที่ปลอดภัย</h4><p>การแชร์หน้าจอจริงต้องได้รับการอนุญาตจากเครื่องปลายทางทุกครั้งผ่านเบราว์เซอร์</p></div></div></section>
 </div>`}
function deviceRow(d){return `<div class="device-row"><div class="dev-mark">${icon(d.icon,19)}</div><div class="device-row-meta"><div class="device-row-title"><strong>${e(d.name)}</strong><i class="status-dot ${d.status==='online'?'':'offline'}"></i></div><div class="dev-desc"><span>${e(d.alias)}</span><span>·</span><span>${e(d.os)}</span></div></div><div class="device-row-extra">${icon('screens',14)} ${d.monitors.length} จอ</div><button class="btn btn-xs ${d.status==='online'?'btn-primary':''}" data-act="open-device" data-device="${e(d.id)}" ${d.status!=='online'?'disabled':''}>${icon('arrow',13)} รีโมต</button></div>`}
function activityRow(a){return `<div class="activity-row"><div class="activity-icon">${icon(a.type==='connect'?'monitor':a.type==='shield'?'shield':a.type==='files'?'files':a.type==='alert'?'alert':'wifi',16)}</div><div class="activity-text"><strong>${e(a.title)}</strong><div>${e(a.sub)}</div></div><span class="activity-time">${e(a.time)}</span></div>`}
function devicesPage(){let list=state.devices.filter(d=>(state.filter==='all'||d.status===state.filter)&&(d.name+' '+d.alias+' '+d.location).toLowerCase().includes(state.search.toLowerCase()));return `<div class="content">
 ${header('DEVICE MANAGER','อุปกรณ์ทั้งหมด','จัดการเครื่อง Windows และเลือกรูปแบบการเชื่อมต่อได้ตามต้องการ',`${btn(`${icon('share')} แชร์เครื่องนี้`,'go-host')}${btn(`${icon('plus')} จับคู่เครื่อง`,'connect-code','btn btn-primary')}`)}
 <div class="info-banner">${icon('info',17)} รายชื่อด้านล่างเป็นเครื่องจำลองสำหรับทดสอบ UI ไม่ใช่รายชื่ออุปกรณ์จริง เมื่อใช้ Host Share จะเชื่อมต่อกับหน้าต่างหรือจอที่เจ้าของเครื่องยินยอมแชร์</div>
 <div class="controls-row"><div class="search-box">${icon('search',16)}<input id="device-search" placeholder="ค้นหาชื่อเครื่อง สถานที่ หรือผู้ใช้งาน..." value="${e(state.search)}" /></div>
 <select id="device-filter" class="choice"><option value="all" ${state.filter==='all'?'selected':''}>ทุกสถานะ</option><option value="online" ${state.filter==='online'?'selected':''}>ออนไลน์</option><option value="offline" ${state.filter==='offline'?'selected':''}>ออฟไลน์</option></select>
 <div class="segmented"><button data-act="grid-view" class="${state.deviceView==='grid'?'active':''}">${icon('grid2',14)} การ์ด</button><button data-act="list-view" class="${state.deviceView==='list'?'active':''}">${icon('list',14)} รายการ</button></div></div>
 ${list.length?state.deviceView==='grid'?`<div class="device-grid">${list.map(deviceCard).join('')}</div>`:`<div class="panel">${list.map(deviceRow).join('')}</div>`:`<div class="panel no-results">${icon('search',32)} ไม่พบอุปกรณ์ที่ตรงกับคำค้นหา</div>`}
 </div>`}
function deviceCard(d){return `<div class="panel device-card"><div class="device-head"><div class="dev-mark large">${icon(d.icon,23)}</div>${onlineStatus(d.status)}</div><h3>${e(d.name)}</h3><div class="alias">${e(d.alias)}</div><div class="device-tags"><span class="pill">${icon('windows',12)} ${e(d.os)}</span><span class="pill">${icon('screens',12)} ${d.monitors.length} จอ</span></div><div class="device-meta"><span>${icon('globe',13)} ${e(d.location)}</span><span>${d.latency?d.latency+' ms':d.last}</span></div><div class="device-bottom"><button class="btn ${d.status==='online'?'btn-primary':''}" data-act="open-device" data-device="${e(d.id)}" ${d.status!=='online'?'disabled':''}>${icon('monitor',15)} เข้าใช้งาน</button><button class="btn btn-icon" data-act="device-info" data-device="${e(d.id)}" title="รายละเอียด">${icon('dots',17)}</button></div></div>`}
function mockWindow(app='Excel',idx=0){const meta=nameApp(app);let body='';
 if(app==='Excel')body=`<div class="window-ribbon">แฟ้ม　 หน้าแรก　 แทรก　 เค้าโครงหน้ากระดาษ　 สูตร　 ข้อมูล　 ตรวจทาน</div><table class="grid-sheet"><thead><tr><th>#</th><th>ชื่อ-นามสกุล</th><th>คะแนนเก็บ</th><th>สอบ</th><th>รวม</th></tr></thead><tbody>${['กมลชนก แก้วดี','ธนกร ใจงาม','ปรียาภรณ์ แสนสุข','พิชญุตม์ สุขใจ','วรัญญา พิมพ์ทอง'].map((n,i)=>`<tr><td>${i+1}</td><td>${n}</td><td>${34+i*2}</td><td>${42-i}</td><td class="${i===2?'highlight':''}">${76+i}</td></tr>`).join('')}</tbody></table>`;
 else if(app==='Chrome')body=`<div class="browser-address">🔒 https://school.krabak.ac.th</div><div class="browser-page"><div class="browser-bubble">KRABAK <span style="color:#31c4a4">ONE</span></div><div style="font-size:10px;color:#6d829b;margin-top:4px">ระบบบริหารจัดการโรงเรียน</div><div class="browser-search"></div><div class="browser-shortcuts"><span></span><span></span><span></span><span></span></div></div>`;
 else if(app==='VS Code')body=`<div class="editor-window"><div class="editor-sidebar">EXPLORER<br/>▼ krabak-remote<br/>　src<br/>　server<br/>　main.ts<br/>　config.json</div><div class="code-lines"><span class="editor-blue">const</span> <span class="editor-green">workspace</span> = {<br/>　<span class="editor-orange">name</span>: <span class="editor-green">'KRABAK'</span>,<br/>　<span class="editor-orange">remote</span>: <span class="editor-blue">true</span>,<br/>　<span class="editor-orange">monitors</span>: ${idx+1},<br/>　<span class="editor-orange">secure</span>: <span class="editor-blue">true</span><br/>};<br/><br/><span class="editor-blue">export default</span> workspace;</div></div>`;
 else if(app==='PowerShell')body=`<div class="terminal-window">Windows PowerShell<br/>Copyright (C) Microsoft Corporation.<br/><br/>PS C:\\KRABAK&gt; Get-ComputerInfo<br/>WindowsProductName : Windows 11 Pro<br/>CsName : KRABAK-OFFICE-01<br/><br/>PS C:\\KRABAK&gt; _</div>`;
 else if(app==='File Explorer')body=`<div class="window-ribbon">Home　 ›　 Documents　 ›　 KRABAK</div><div class="explorer-window">${['School','Reports','Projects','Exports','Documents'].map(n=>`<div class="folder-tile">${icon('folder',25)} ${n}</div>`).join('')}</div>`;
 else body=`<div class="window-ribbon">ไฟล์　 หน้าแรก　 แทรก　 มุมมอง</div><div style="height:100%;background:white;padding:20px;font-size:10px;color:#26374d"><strong>งานเอกสารโรงเรียนกระบากวิทยาคาร</strong><hr/><p>ตัวอย่างเนื้อหาเอกสารในการทำงานทางไกล</p><p>ขณะนี้แสดงหน้าต่างแอปพลิเคชันจำลอง</p></div>`;
 return `<div class="mock-app-window"><div class="window-top"><span style="display:flex;align-items:center;gap:6px"><span style="color:${meta.color}">${icon(meta.icon,14)}</span>${e(meta.title)}</span><span class="window-controls">− □ ×</span></div><div class="window-body">${body}</div></div>`;}
function monitorPreview(idx=0, app='Excel',onlyWindow=false){return `<div class="monitor-preview" data-monitor-render="${idx}"><div class="mock-win-bar"><span class="mock-start">${icon('windows',14)} Windows 11</span><span style="margin-left:auto;color:#adc7ff">${e(state.device.name)} · Display ${idx+1}</span></div><div class="mock-desktop">${mockWindow(app,idx)}</div><div class="mock-taskbar">${icon('windows',13)}${icon('folder',13)}${icon('chrome',13)}${icon('code',13)}${icon('excel',13)}<span style="margin-left:auto;margin-right:12px;font-size:9px">${now()}</span></div></div>`;}
function remotePage(){const live=hasLive();const d=state.device||demoDevices[0];const apps=d.apps||['Chrome','Excel'];const mons=d.monitors||[{name:'จอหลัก',res:'1920 × 1080'}];const selected=apps.includes(state.app)?state.app:apps[0];
 const tools=`${btn(`${icon('keyboard',14)} แป้นพิมพ์`,'keyboard','tool-button','title="ส่งคีย์ลัด (โหมดจำลอง)"')}${btn(`${icon('clipboard',14)} คัดลอกข้อความ`,'clipboard-modal','tool-button','title="คลิปบอร์ด"')}${btn(`${icon('fullscreen',14)}`,'fullscreen','tool-button','title="เต็มหน้าจอ"')}`;
 return `<div class="remote-content">
 <div class="page-head" style="margin-bottom:17px"><div><div class="eyebrow">REMOTE SESSION ${live?'/ BROWSER SHARE':'/ INTERACTIVE DEMO'}</div><h1 class="heading" style="font-size:25px">${e(live?state.liveSession.hostName:d.alias)}</h1><div class="subtitle device-topline">${onlineStatus('online')}<span>${icon('shield',13)} ${live?'เจ้าของเครื่องอนุมัติการแชร์':'โหมดตัวอย่าง ไม่ได้ควบคุมเครื่องจริง'}</span>${live?`<span class="pill info">${e(state.connection)}</span>`:''}</div></div><div class="head-buttons">${btn(`${icon('back',14)} กลับอุปกรณ์`,'go-devices')}${btn(`${icon('power',14)} จบการเชื่อมต่อ`,live?'end-live':'end-demo','btn btn-danger')}</div></div>
 <div class="remote-layout">
 <div class="remote-side"><div class="panel remote-nav-panel"><h3>${icon('screens',16)} โหมดการแสดงผล</h3>
 <button class="source-option ${state.mode==='monitor'?'selected':''}" data-act="mode-monitor">${icon('monitor',17)}<div><strong>เต็มหน้าจอ</strong><small>${live?'แหล่งที่เจ้าของเครื่องแชร์':'เลือกจอภาพที่ต้องการ'}</small></div>${icon('check',14)}</button>
 <button class="source-option ${state.mode==='window'?'selected':''}" data-act="mode-window">${icon('grid2',17)}<div><strong>เฉพาะแอป</strong><small>${live?'เปลี่ยนผ่านเจ้าของเครื่อง':'เลือกหน้าต่างได้อิสระ'}</small></div>${icon('check',14)}</button>
 ${!live?`<div class="divider"></div><div class="section-kicker">จอภาพ (${mons.length})</div>${mons.map((m,i)=>`<button class="source-option ${state.monitor===i?'selected':''}" data-act="monitor" data-idx="${i}">${icon('monitor',17)}<div><strong>${e(m.name)}</strong><small>${e(m.res)}</small></div>${state.monitor===i?icon('check',14):''}</button>`).join('')}<button class="source-option ${state.multi?'selected':''}" data-act="toggle-multi">${icon('screens',17)}<div><strong>ดูหลายจอพร้อมกัน</strong><small>มุมมองรวมทุกจอ</small></div></button>`:''}</div>
 <div class="panel remote-nav-panel"><h3>${icon('grid2',16)} ${live?'สิทธิ์การควบคุม':'แอปพลิเคชันที่เปิดอยู่'}</h3>
 ${live?`<p>โหมดนี้แชร์ภาพจริงผ่าน WebRTC และดูอย่างเดียว การคลิกหรือพิมพ์ลงโปรแกรม Windows ต้องใช้ Windows Agent เพิ่มเติม</p><span class="pill warning">${icon('lock',12)} View only</span>${btn(`${icon('refresh',13)} ขอเปลี่ยนหน้าต่าง`,'request-change','btn btn-xs mt-16 w-full')}`:apps.map(a=>`<div class="app-option ${selected===a&&state.mode==='window'?'active':''}" data-act="select-app" data-app="${e(a)}"><span class="app-icon" style="color:${nameApp(a).color}">${icon(nameApp(a).icon,16)}</span><span style="flex:1">${e(nameApp(a).title)}</span>${selected===a&&state.mode==='window'?icon('check',13):''}</div>`).join('')}
 </div></div>
 <section class="remote-stage" id="remote-stage"><div class="stage-top"><div class="stage-title">${icon('monitor',14)} ${live?'LIVE · '+e(state.liveSession.hostName):e(d.name)} ${live?'':'• '+e(state.mode==='window'?selected:'Display '+(state.monitor+1))}</div><div class="stage-control">${btn(`${icon('sliders',14)}`,'quality','tool-button','title="คุณภาพภาพ"')}${btn(`${icon('expand',14)}`,'fit','tool-button','title="พอดีหน้าจอ"')}${btn(`${icon('fullscreen',14)}`,'fullscreen','tool-button','title="เต็มหน้าจอ"')}</div></div>
 <div class="stage-body" id="remote-stage-body">${live?`<div class="capture-frame" id="live-placeholder">${icon('video',40)}<div>กำลังรอภาพจากเครื่องปลายทาง<br/><small>หากไม่มีภาพ ให้ตรวจสอบการอนุญาตแชร์หน้าจอ</small></div></div><video id="live-video" class="fit-video hidden" autoplay playsinline></video>`:state.multi?`<div class="multi-preview">${mons.map((m,i)=>monitorPreview(i,apps[i%apps.length],false)).join('')}</div>`:state.mode==='window'?`<div class="isolated-app">${mockWindow(selected,state.monitor)}</div>`:monitorPreview(state.monitor,apps[state.monitor%apps.length])}</div>
 <div class="stage-bottom"><span>${icon('wifi',12)} ${live?'WebRTC · E2E media encryption':'DEMO · ไม่เชื่อมต่อ Windows'}</span><span>${live?'Live view':e(mons[state.monitor]?.res)} &nbsp; • &nbsp; ${state.zoom}%</span><span>${icon('shield',12)} ${live?'Consent based':'Sample only'}</span></div>
 <div style="padding:10px;display:flex;justify-content:center;gap:7px;flex-wrap:wrap;border-top:1px solid #27334c">${tools}${btn(`${icon('plus',14)} ซูม`,'zoom-in','tool-button')}${btn(`− ซูม`,'zoom-out','tool-button')}${btn(`${icon('chat',14)} แชต`,'tab-chat','tool-button')}${btn(`${icon('files',14)} ไฟล์`,'tab-files','tool-button')}</div></section>
 <aside class="panel right-panel"><div class="right-tab"><button class="${state.right==='chat'?'active':''}" data-act="tab-chat">${icon('chat',13)} แชต</button><button class="${state.right==='files'?'active':''}" data-act="tab-files">${icon('files',13)} ไฟล์</button><button class="${state.right==='info'?'active':''}" data-act="tab-info">${icon('info',13)} รายละเอียด</button></div>
 ${state.right==='chat'?`<div class="right-body" style="display:flex;flex-direction:column"><div style="font-size:10px;color:#8291aa">${live?'ข้อความระหว่างเบราว์เซอร์สองฝั่ง':'ข้อความทดสอบในเซสชันจำลอง'}</div><div id="chat-messages" style="flex:1;overflow:auto;max-height:400px">${(live?state.hostChat:state.chat).map(c=>`<div class="chat-bubble ${c.mine?'mine':''}">${e(c.text)}<div class="chat-time">${e(c.time)}</div></div>`).join('')}</div></div><form id="chat-form" class="chat-compose"><input id="chat-input" placeholder="พิมพ์ข้อความ..." autocomplete="off"/><button aria-label="ส่งข้อความ" type="submit">${icon('arrow',15)}</button></form>`:
 state.right==='files'?`<div class="right-body"><div class="file-zone" data-act="send-file">${icon('upload',24)}<strong>ส่งไฟล์ไปเครื่องปลายทาง</strong><small>${live?'ไฟล์ส่งผ่านช่อง WebRTC เมื่อเชื่อมต่อสำเร็จ':'เลือกไฟล์เพื่อจำลองการส่ง'}</small></div><input type="file" id="remote-file" class="hidden"/><div style="margin-top:16px" class="section-kicker">ไฟล์ในเซสชัน</div>${state.files.length?state.files.map(f=>`<div class="file-item">${icon('file',18)}<div><strong>${e(f.name)}</strong><small>${e(f.status)}</small></div>${f.url?`<button class="btn btn-xs" data-act="download-file" data-file-id="${e(f.id)}">บันทึก</button>`:""}</div>`).join(''):`<div class="no-results" style="padding:23px 4px">ยังไม่มีการส่งไฟล์</div>`}</div>`:
 `<div class="right-body"><h3 style="font-size:13px">ข้อมูลการเชื่อมต่อ</h3>${[['ชื่อเครื่อง',live?state.liveSession.hostName:d.name],['ระบบปฏิบัติการ',live?'ตามเครื่องที่แชร์':d.os],['โหมด',live?'Browser share (view-only)':state.mode==='window'?'เฉพาะหน้าต่าง':'ทั้งจอ'],['จอภาพ',live?'ผู้แชร์เลือกเอง':mons.length+' จอ'],['คุณภาพ',state.quality],['ข้อมูลตัวอย่าง',live?'ไม่ใช่':'ใช่']].map(([k,v])=>`<div class="detail-row"><span>${e(k)}</span><strong>${e(v)}</strong></div>`).join('')}<div class="remote-help">${icon('shield',15)} การควบคุมเมาส์/คีย์บอร์ดระบบ Windows ต้องติดตั้ง Windows Agent เพิ่มเติม จึงไม่สามารถทำได้จากเบราว์เซอร์อย่างเดียว</div></div>`}
 </aside></div></div>`;}
function activityPage(){return `<div class="content">${header('AUDIT & ACTIVITY','ประวัติการใช้งาน','ติดตามการเข้าถึงอุปกรณ์และเหตุการณ์ในระบบ',btn(`${icon('refresh')} รีเฟรช`,'refresh-audit'))}<div class="info-banner">${icon('info',17)} กิจกรรมบางส่วนเป็นข้อมูลจำลอง ส่วนบันทึกเซิร์ฟเวอร์จริงจะแสดงเมื่อเข้าสู่ระบบ Backend สำเร็จ</div><div class="panel panel-pad"><div class="panel-title mb-20"><h2>บันทึกเหตุการณ์</h2><span class="pill">ล่าสุดก่อน</span></div>${state.events.map(activityRow).join('')}</div></div>`}
function filesPage(){return `<div class="content">${header('FILE WORKSPACE','ไฟล์และการถ่ายโอน','จัดการการส่งไฟล์ระหว่างเซสชันอย่างเป็นระเบียบ',btn(`${icon('upload',16)} ส่งไฟล์`,'files-help','btn btn-primary'))}<div class="info-banner">${icon('shield',16)} ไม่เก็บไฟล์ระหว่างเซสชันไว้บนเซิร์ฟเวอร์โดยอัตโนมัติ การส่งไฟล์จริงใช้ WebRTC DataChannel และต้องมีการเชื่อมต่ออยู่</div><div class="dashboard-cols"><div class="panel panel-pad"><div class="panel-title"><div><h2>ไฟล์ในเซสชัน</h2><p>การส่งและรับไฟล์ที่เกี่ยวข้องกับหน้าจอรีโมต</p></div></div>${state.files.length?state.files.map(f=>`<div class="file-item">${icon('file',18)}<div><strong>${e(f.name)}</strong><small>${e(f.status)}</small></div>${f.url?`<button class="btn btn-xs" data-act="download-file" data-file-id="${e(f.id)}">บันทึก</button>`:""}</div>`).join(''):`<div class="no-results"><div class="folder-illustration">${icon('files',44)}</div><h3>ยังไม่มีไฟล์ในเซสชันนี้</h3><p>เปิดหน้าจอรีโมต แล้วเลือกแท็บไฟล์เพื่อเริ่มส่ง</p>${btn(`${icon('arrow',14)} เปิดเซสชันตัวอย่าง`,'demo-remote','btn btn-primary')}</div>`}</div><div class="panel panel-pad"><h2 style="font-size:15px">ข้อควรรู้เรื่องการโอนไฟล์</h2><div class="help-wrap"><h4>WebRTC DataChannel</h4><p>สามารถส่งข้อมูลระหว่างเบราว์เซอร์ผ่านการเชื่อมต่อที่เข้ารหัส แต่การบันทึกไฟล์ลงตำแหน่งปลายทางต้องให้ผู้รับยืนยัน</p></div><div class="help-wrap"><h4>Windows Agent (แผนพัฒนา)</h4><p>จะเพิ่ม File Manager เพื่อเปิดโฟลเดอร์และโอนไฟล์จาก Windows โดยตรงผ่านสิทธิ์ที่ได้รับอนุญาต</p></div></div></div></div>`}
function settingsPage(){const s=state.settings;return `<div class="content">${header('PREFERENCES & SECURITY','ตั้งค่าการใช้งาน','ปรับหน้าตาและพฤติกรรมของเว็บรีโมตบนอุปกรณ์นี้',`${btn(`${icon('refresh')} คืนค่าเริ่มต้น`,'reset-settings')}`)}<div class="settings-grid"><div class="panel panel-pad"><div class="panel-title"><div><h2>การแสดงผลและเซสชัน</h2><p>ตั้งค่ารูปแบบการควบคุมที่คุณใช้งานเป็นประจำ</p></div>${icon('sliders',20)}</div><div class="field"><label>ธีมหน้าเว็บ</label><select data-setting="theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Dark — Midnight</option><option value="light" ${s.theme==='light'?'selected':''}>Light — Daylight</option></select></div><div class="field"><label>คุณภาพการแสดงผลเริ่มต้น</label><select data-setting="quality"><option value="speed" ${s.quality==='speed'?'selected':''}>ความเร็วเป็นหลัก</option><option value="balanced" ${s.quality==='balanced'?'selected':''}>สมดุล (แนะนำ)</option><option value="quality" ${s.quality==='quality'?'selected':''}>ความคมชัดเป็นหลัก</option></select><small>ต้นแบบนี้เป็นตัวเลือก UI ยังไม่เปลี่ยนการเข้ารหัสของแหล่งภาพ</small></div><div class="field"><label>โหมดการเชื่อมต่อเริ่มต้น</label><select data-setting="defaultMode"><option value="window" ${s.defaultMode==='window'?'selected':''}>เฉพาะแอปพลิเคชัน</option><option value="monitor" ${s.defaultMode==='monitor'?'selected':''}>เต็มจอ</option></select></div>${settingSwitch('clipboard','คลิปบอร์ด','เปิดใช้การวางข้อความด้วยความยินยอมของผู้ใช้')}${settingSwitch('notifications','การแจ้งเตือน','แสดงข้อความเมื่อมีคำขอเชื่อมต่อหรือไฟล์เข้า')}${settingSwitch('conserve','ประหยัดแบนด์วิดท์','จัดลำดับการส่งข้อมูลตามคุณภาพเครือข่าย (แผนพัฒนา)')}</div>
 <div class="panel panel-pad"><div class="panel-title"><div><h2>ความปลอดภัยและบัญชี</h2><p>ข้อมูลที่ใช้เชื่อมต่อกับ Serva VPS</p></div>${icon('shield',20)}</div>${[['สถานะ Backend',state.backend?'ติดต่อได้':'ไม่ได้เชื่อมต่อ'],['บัญชีผู้ดูแล',state.account?.email||'ไม่ได้เข้าสู่ระบบ'],['การแชร์หน้าจอ','ต้องอนุญาตทุกครั้ง'],['สิทธิ์ควบคุม Windows','ต้องใช้ Agent']].map(([k,v])=>`<div class="detail-row"><span>${e(k)}</span><strong>${e(v)}</strong></div>`).join('')}<div class="mt-20">${state.account?btn(`${icon('lock')} ออกจากระบบ`,'logout','btn btn-danger w-full'):btn(`${icon('lock')} เข้าสู่ระบบ Backend`,'go-login','btn btn-primary w-full')}</div><div class="help-wrap"><h4>${icon('info',14)} การใช้งานจริง</h4><p>เซิร์ฟเวอร์ต้องอยู่หลัง HTTPS และควรเปิดใช้งาน MFA, จำกัดสิทธิ์ต่อเครื่อง, ทำ Audit และจัดการ TURN ก่อนเปิดใช้ภายนอกองค์กร</p></div><div class="mt-20">${btn(`${icon('phone',16)} ${state.installPrompt?'ติดตั้ง PWA':'วิธีติดตั้ง PWA'}`,'install-pwa','btn w-full')}</div></div></div></div>`}
function settingSwitch(key,title,desc){return `<div class="switch-row"><div><strong>${title}</strong><p>${desc}</p></div><button class="switch ${state.settings[key]?'on':''}" data-act="toggle-setting" data-key="${key}" role="switch" aria-checked="${state.settings[key]}"></button></div>`}
function hostPage(){return `<div class="host-wrapper"><div class="host-header"><div class="brand-logo">${icon('monitor',30)}</div><div class="eyebrow">SECURE SCREEN SHARING</div><h1>แชร์หน้าจอหรือแอปพลิเคชัน</h1><p>เครื่องปลายทางเลือกแชร์เฉพาะหน้าต่างแอป จอภาพ หรือแท็บเบราว์เซอร์ได้ด้วยตนเอง<br/>ข้อมูลภาพส่งผ่านการเชื่อมต่อ WebRTC หลังอนุมัติเท่านั้น</p><a href="#/dashboard" class="text-link">${icon('back',14)} กลับไปแดชบอร์ด</a></div>
 <div class="panel host-card"><div class="panel-title"><div><h2>เครื่องที่กำลังแชร์</h2><p>ไม่ต้องติดตั้งโปรแกรมสำหรับการดูภาพผ่านเบราว์เซอร์</p></div><span class="pill ${state.hostCode?'success':'purple'}">${state.hostCode?'รอผู้เข้าร่วม':'ไม่ได้เริ่มแชร์'}</span></div>
 <div class="host-step"><div class="host-step-index">1</div><div style="flex:1"><strong>ตั้งชื่ออุปกรณ์</strong><p>ตั้งชื่อที่ผู้เชื่อมต่อจดจำได้ง่าย</p><div class="field"><input id="host-name" value="${e(state.hostName||'Windows ของฉัน')}" placeholder="เช่น คอมพิวเตอร์ห้องธุรการ" ${state.hostCode?'disabled':''}/></div></div></div>
 <div class="host-step"><div class="host-step-index">2</div><div style="flex:1"><strong>สร้างรหัสจับคู่ชั่วคราว</strong><p>ให้ผู้ดูแลระบบเปิดเมนู “เชื่อมต่อเครื่องใหม่” และกรอกรหัสนี้ รหัสจะหมดอายุอัตโนมัติ</p>${state.hostCode?`<div class="pair-code">${e(state.hostCode)}</div><div style="text-align:center;font-size:11px;color:#8999b2;margin-bottom:10px">ใช้ครั้งเดียว · หมดอายุประมาณ 15 นาที</div><div style="text-align:center">${btn(`${icon('copy',14)} คัดลอกรหัส`,'copy-host-code','btn btn-xs')}${btn(`${icon('refresh',14)} รหัสใหม่`,'regenerate-host','btn btn-xs')}${btn(`${icon('close',14)} ยกเลิก`,'stop-host','btn btn-xs btn-danger')}</div>`:btn(`${icon('plus',15)} สร้างรหัสสำหรับแชร์เครื่องนี้`,'start-host','btn btn-primary w-full mt-16')}
 </div></div>
 <div class="host-step"><div class="host-step-index">3</div><div style="flex:1"><strong>อนุมัติคำขอและเลือกหน้าต่าง</strong><p>เมื่อผู้ดูแลขอเชื่อมต่อ ให้คลิก “อนุญาตและเลือกหน้าต่าง” เบราว์เซอร์จะเปิดหน้าต่างเลือกแชร์ โดยคุณเป็นผู้ตัดสินใจทุกครั้ง</p><div class="host-requests">${state.hostRequests.length?state.hostRequests.map(r=>`<div class="request-card"><strong>${icon('shield',15)} คำขอจาก ${e(r.requester||'ผู้ดูแลระบบ')}</strong><p>ขอดูภาพหน้าจอ/หน้าต่างของคุณ (ดูอย่างเดียว)</p><div style="display:flex;gap:7px">${btn(`${icon('check',14)} อนุญาตและเลือกแหล่งแชร์`,'accept-host','btn btn-primary','data-session="'+e(r.sessionId)+'"')}${btn('ปฏิเสธ','reject-host','btn btn-danger','data-session="'+e(r.sessionId)+'"')}</div></div>`).join(''):`<div class="help-wrap"><h4>${icon('lock',14)} ยังไม่มีคำขอเชื่อมต่อ</h4><p>${state.hostCode?'รอให้ผู้ดูแลใส่รหัสจับคู่ แล้วกดยอมรับที่เครื่องนี้':'สร้างรหัสจับคู่ก่อน เพื่อให้ผู้ดูแลส่งคำขอเข้ามาได้'}</p></div>`}</div></div></div>
 <div class="host-step"><div class="host-step-index">4</div><div style="flex:1"><strong>ภาพที่กำลังแชร์</strong><p>ภาพนี้เป็นการแสดงตัวอย่างก่อนหรือระหว่างส่งสตรีม</p><div class="host-preview"><video id="host-video" autoplay muted playsinline ${state.localStream?'':'class="hidden"'}></video>${state.localStream?'':`<div class="capture-frame">${icon('monitor',34)}<span>ยังไม่มีหน้าต่างที่กำลังแชร์</span></div>`}</div>${state.localStream?`<div class="mt-16">${btn(`${icon('power',14)} หยุดแชร์ทันที`,'stop-stream','btn btn-danger w-full')}</div>`:''}</div></div>
 </div><div class="info-banner warning mt-20" style="max-width:590px;margin-left:auto;margin-right:auto">${icon('alert',17)} เว็บเบราว์เซอร์ส่งภาพจากแอปหรือจอที่คุณเลือกได้ แต่ไม่สามารถรับคำสั่งเมาส์/คีย์บอร์ดเพื่อควบคุมโปรแกรม Windows จริงได้หากไม่มี Windows Agent</div>
 ${state.localStream?`<div class="panel host-card mt-16"><div class="panel-title"><h2>การสื่อสารกับผู้ดูแล</h2><span class="pill success">Session live</span></div><div style="max-height:220px;overflow:auto;margin-top:15px">${state.hostChat.map(c=>`<div class="chat-bubble ${c.mine?'mine':''}">${e(c.text)}</div>`).join('')}</div><form id="host-chat-form" class="chat-compose"><input id="host-chat-input" placeholder="ส่งข้อความกลับผู้ดูแล"/><button aria-label="ส่งข้อความ">${icon('arrow',14)}</button></form><input class="hidden" type="file" id="host-file"/>${state.files.length?`<div style="margin-top:10px">${state.files.map(f=>`<div class="file-item">${icon('file',16)}<div style="flex:1"><strong>${e(f.name)}</strong><small>${e(f.status)}</small></div>${f.url?`<button class="btn btn-xs" data-act="download-file" data-file-id="${e(f.id)}">บันทึก</button>`:''}</div>`).join('')}</div>`:''}${btn(`${icon('upload',14)} ส่งไฟล์ให้ผู้ดูแล`,'host-send-file','btn w-full mt-16')}</div>`:''}
 </div>`}
function loginPage(){return `<div class="login-screen"><div class="login-visual"><div class="brand"><div class="brand-logo">${icon('monitor',24)}</div><div><div class="brand-head">KRABAK</div><div class="brand-sub">REMOTE MANAGER</div></div></div><div><div class="eyebrow">SECURE REMOTE WORKSPACE</div><h1>ทำงานทุกที่<br/>เข้าถึงทุกอุปกรณ์<br/><span class="text-purple">ปลอดภัยในทุกเซสชัน</span></h1><p>Remote management workspace สำหรับระบบ KRABAK<br/>พร้อมระบบรหัสจับคู่และการยินยอมก่อนแชร์ภาพ</p><div class="hero-graphic"><div class="hg-monitor hg-main"><div class="hg-toolbar"><i></i><i></i><i></i></div><div class="hg-shapes"><div></div><div></div></div></div><div class="hg-monitor hg-small"><div class="hg-toolbar"><i></i><i></i></div><div class="hg-shapes"><div></div></div></div></div></div><span style="font-size:11px;color:#8c97b5">Serva VPS · aaPanel Free · Self-hosted</span></div><div class="login-form"><div class="login-form-inner"><div class="eyebrow">WELCOME BACK</div><h2>เข้าสู่ระบบผู้ดูแล</h2><p>ใช้บัญชีที่สร้างบนเซิร์ฟเวอร์ด้วยคำสั่ง <code>npm run setup:admin</code></p><form id="login-form"><div class="field"><label>อีเมลผู้ดูแล</label><input required type="email" id="login-email" autocomplete="username" placeholder="admin@yourdomain.tld"/></div><div class="field"><label>รหัสผ่าน</label><input required type="password" id="login-password" autocomplete="current-password" placeholder="••••••••••••"/></div><button class="btn btn-primary w-full mt-16" type="submit">${icon('lock',15)} เข้าสู่ระบบอย่างปลอดภัย</button></form>${state.apiError?`<p style="color:#f0a1a9">${e(state.apiError)}</p>`:''}<div class="divider"></div><p>ต้องการทดลอง UI ก่อนเปิดใช้งานเซิร์ฟเวอร์?</p>${btn(`${icon('spark',16)} เข้าสู่โหมดสาธิต`,'demo-mode','btn w-full')}<p class="mt-20">${icon('shield',14)} การแชร์หน้าจอจริงต้องได้รับการยอมรับจากเจ้าของเครื่องทุกครั้ง</p></div></div></div>`}
function modalHtml(){if(!state.modal)return '';let body='',title='';const m=state.modal;
 if(m.type==='connect'){title='เชื่อมต่อเครื่องด้วยรหัสจับคู่';body=`<p>เปิดเมนู “แชร์เครื่องนี้” บนเครื่องปลายทาง จากนั้นนำรหัสชั่วคราวมากรอกที่นี่</p><form id="pair-form"><div class="field"><label>รหัสจับคู่</label><input id="pair-code" class="code-input" placeholder="XXXXXXXX" maxlength="8" autocomplete="off" required pattern="[a-zA-Z0-9]{8}"/><small>ต้องมีบัญชีผู้ดูแลและเชื่อมต่อ Backend เพื่อใช้งานจริง</small></div><div class="modal-actions"><button type="button" class="btn" data-act="close-modal">ยกเลิก</button><button type="submit" class="btn btn-primary">${icon('arrow',15)} ขอเชื่อมต่อ</button></div></form>`;}
 else if(m.type==='device'){title='รายละเอียดอุปกรณ์';const d=m.device;body=`<div class="device-topline">${onlineStatus(d.status)} <span class="pill">${e(d.os)}</span></div><h3 style="margin:18px 0 6px">${e(d.name)}</h3><p>${e(d.alias)}</p>${[['สถานที่',d.location],['ผู้ดูแล',d.owner],['จอภาพ',d.monitors.length+' จอ'],['โปรแกรม',d.apps.join(', ')],['สถานะ','ข้อมูลจำลอง']].map(([k,v])=>`<div class="detail-row"><span>${e(k)}</span><strong>${e(v)}</strong></div>`).join('')}<div class="modal-actions">${btn('ปิด','close-modal')}${d.status==='online'?btn('เปิดตัวอย่างรีโมต','info-remote','btn btn-primary'):''}</div>`;}
 else if(m.type==='clipboard'){title='คลิปบอร์ดและข้อความ';body=`<p>ส่งข้อความไปยังอีกฝั่งของเซสชันเพื่อให้ผู้รับเลือกคัดลอกเอง ไม่อ่านคลิปบอร์ดอัตโนมัติ</p><form id="clipboard-form"><div class="field"><label>ข้อความที่ต้องการส่ง</label><textarea id="clipboard-text" rows="5" placeholder="วางข้อความที่นี่..." required></textarea></div><div class="modal-actions">${btn('ยกเลิก','close-modal')}<button type="submit" class="btn btn-primary">${icon('clipboard',14)} ส่งข้อความ</button></div></form>`;}
 else if(m.type==='keyboard'){title='คีย์ลัดสำหรับรีโมต';body=`<p>เครื่องมือจำลองการส่งชุดคีย์ ควบคุมโปรแกรม Windows จริงต้องติดตั้ง Agent และมีสิทธิ์ที่ได้รับอนุญาต</p><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px">${['Ctrl + C','Ctrl + V','Alt + Tab','Win + D','Ctrl + Shift + Esc','Ctrl + Alt + Del'].map(x=>btn(`${icon('keyboard',14)} ${x}`,'demo-key','btn','data-keycombo="'+e(x)+'"')).join('')}</div><div class="modal-actions">${btn('ปิด','close-modal')}</div>`;}
 else if(m.type==='quality'){title='คุณภาพภาพและการเชื่อมต่อ';body=`<p>เลือกรูปแบบที่เหมาะกับความเร็วอินเทอร์เน็ต (ยังเป็นตัวเลือกสำหรับการพัฒนาต่อใน Live mode)</p><div class="field"><label>โหมดคุณภาพ</label><select id="quality-input"><option value="speed" ${state.quality==='speed'?'selected':''}>เน้นความเร็ว · ลดความละเอียด</option><option value="balanced" ${state.quality==='balanced'?'selected':''}>สมดุล</option><option value="quality" ${state.quality==='quality'?'selected':''}>เน้นความคมชัด</option></select></div><div class="field"><label>ระดับซูม</label><input id="zoom-range" type="range" min="50" max="150" step="10" value="${state.zoom}"/><small>${state.zoom}%</small></div><div class="modal-actions">${btn('บันทึกการตั้งค่า','save-quality','btn btn-primary')}</div>`;}
 else if(m.type==='help'){title='เกี่ยวกับ KRABAK Remote Manager';body=`<div class="info-banner mint">${icon('check',16)} เว็บนี้มีหน้าตัวอย่างแบบโต้ตอบ และมีระบบแชร์ภาพจากเบราว์เซอร์จริงผ่าน WebRTC เมื่อเชื่อมต่อ Backend</div><p><strong>ความสามารถที่ใช้งานได้ในชุดนี้</strong><br/>โหมดสาธิต, เลือกเครื่อง/จอ/แอปจำลอง, แชต, คัดลอกข้อความ, PWA, แชร์หน้าจอ/หน้าต่างแบบเจ้าของเครื่องยินยอม, WebRTC signaling และจัดการรหัสจับคู่</p><p><strong>ยังต้องมี Windows Agent</strong><br/>การคลิก/พิมพ์ในโปรแกรม Windows จริง, เข้าถึงแอปที่เปิดอยู่แบบไม่ต้องให้เจ้าของคลิกแชร์, unattended access, การควบคุมหลายจอจริงแบบแยกจอ, ซิงก์คลิปบอร์ด OS และถ่ายโอนไฟล์ Windows โดยตรง</p><div class="modal-actions">${btn('เข้าใจแล้ว','close-modal','btn btn-primary')}</div>`;}
 else if(m.type==='pwa'){title='ติดตั้งแอป PWA';body=`<p><strong>บน Chrome / Edge (Windows)</strong><br/>เปิดเว็บผ่าน HTTPS แล้วกดไอคอนติดตั้งแอปที่มุมขวาของแถบที่อยู่ หรือเปิดเมนู > ติดตั้งแอปนี้</p><p><strong>บน Android</strong><br/>Chrome > เมนู ⋮ > ติดตั้งแอป / เพิ่มไปยังหน้าจอหลัก</p><p><strong>บน iPhone</strong><br/>Safari > แชร์ > เพิ่มไปยังหน้าจอโฮม</p><div class="modal-actions">${btn('ปิด','close-modal','btn btn-primary')}</div>`;}
 else if(m.type==='confirm-reset'){title='คืนค่าการตั้งค่า';body=`<p>คืนค่าการตั้งค่าหน้าตาและคุณภาพที่บันทึกไว้บนเบราว์เซอร์เครื่องนี้ โดยไม่กระทบข้อมูลบนเซิร์ฟเวอร์</p><div class="modal-actions">${btn('ยกเลิก','close-modal')}${btn('คืนค่าเริ่มต้น','confirm-reset','btn btn-danger')}</div>`;}
 else{title='ข้อมูลเพิ่มเติม';body='<p>รายการนี้ยังอยู่ระหว่างพัฒนา</p>'+btn('ปิด','close-modal')}
 return `<div class="modal-cover" data-overlay="close"><div class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-title"><h3>${title}</h3><button class="top-icon" data-act="close-modal" title="ปิด">${icon('close',17)}</button></div>${body}</div></div>`;
}
function showModal(type,extra={}){state.modal={type,...extra};render();}
function toast(text,kind='ok'){let holder=document.getElementById('toasts');if(!holder){holder=document.createElement('div');holder.id='toasts';document.body.append(holder);}holder.className='toast-stack';const el=document.createElement('div');el.className='toast '+kind;el.innerHTML=`${icon(kind==='err'?'alert':'check',15)}<span>${e(text)}</span>`;holder.appendChild(el);setTimeout(()=>el.remove(),3900);}
function selectDevice(id){const d=demoDevices.find(x=>x.id===id);if(!d)return;state.liveSession=null;state.device=d;state.monitor=0;state.app=d.apps[0];state.multi=false;state.mode=state.settings.defaultMode;state.chat=[{mine:false,text:`เปิดเซสชันจำลองสำหรับ ${d.name} แล้ว`,time:now()}];state.files=[];navigate('remote/demo');}
const api=async(path,opts={})=>{const r=await fetch('/api'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});let body={};try{body=await r.json()}catch{};if(!r.ok)throw new Error(body.error||`HTTP ${r.status}`);return body;};
async function checkBackend(){try{const status=await api('/status');state.backend=true;state.initialised=!!status.initialised;state.rtcConfig=status.rtcConfig||null;try{let me=await api('/me');state.account=me.user;}catch{state.account=null}if(state.account)refreshAudit().catch(()=>{});}catch{state.backend=false;}render();}
async function login(ev){ev.preventDefault();let email=document.getElementById('login-email')?.value.trim(),password=document.getElementById('login-password')?.value;try{const data=await api('/login',{method:'POST',body:JSON.stringify({email,password})});state.account=data.user;state.apiError='';password='';await refreshAudit();toast('เข้าสู่ระบบ Backend เรียบร้อย');navigate('dashboard');}catch(err){state.apiError=err.message;render();}}
async function logout(){try{await api('/logout',{method:'POST',body:'{}'});}catch{}state.account=null;toast('ออกจากระบบแล้ว');navigate('login');}
async function refreshAudit(){if(!state.account)return;const data=await api('/audit');state.events=[...data.events.map(row=>({type:row.type==='login'?'shield':row.type==='session'?'connect':'activity',title:row.title,sub:row.detail||'เหตุการณ์บนเซิร์ฟเวอร์',time:new Date(row.at).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'})})),...activity];if(state.route==='activity')render();}
const wsUrl=()=>`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`;
function connectSocket(role,token){if(state.ws){try{state.ws.close()}catch{}}const ws=new WebSocket(wsUrl());state.ws=ws;ws.onopen=()=>{ws.send(JSON.stringify(role==='host'?{type:'host-hello',token}:{type:'viewer-hello'}));if(role==='viewer'&&state.liveSession)ws.send(JSON.stringify({type:'watch',sessionId:state.liveSession.id}));};ws.onmessage=async event=>{let data;try{data=JSON.parse(event.data)}catch{return}if(data.type==='error'){toast(data.error||'เซิร์ฟเวอร์ปฏิเสธคำขอ','err');return}
 if(data.type==='host-hello-ok'){state.hostStatus='waiting';render();return}
 if(data.type==='viewer-hello-ok'){if(state.liveSession)ws.send(JSON.stringify({type:'watch',sessionId:state.liveSession.id}));return}
 if(data.type==='invite'){state.hostRequests=[...state.hostRequests.filter(r=>r.sessionId!==data.sessionId),data];render();toast('มีคำขอเข้ามา โปรดตรวจสอบก่อนอนุญาต');return}
 if(data.type==='accepted'){state.connection='กำลังเชื่อมต่อ WebRTC';render();return}
 if(data.type==='signal'){await handleSignal(data);return}
 if(data.type==='chat'){state.hostChat.push({mine:false,text:String(data.text||'').slice(0,2000),time:now()});if(state.route==='remote'||state.route==='host')render();toast('มีข้อความใหม่');return}
 if(data.type==='change-request'){toast('ผู้ดูแลขอเปลี่ยนแหล่งภาพ — กดหยุดแชร์แล้วอนุญาตใหม่','ok');return}
 if(data.type==='ended'){state.connection='สิ้นสุดแล้ว';state.sessionEnded=true;closePeer();if(role==='host'){stopStream();state.hostRequests=[];render();}else{toast('เซสชันสิ้นสุดแล้ว');state.liveSession=null;navigate('devices');}return}
 };ws.onerror=()=>toast('ไม่สามารถเชื่อมต่อช่องสัญญาณได้','err');ws.onclose=()=>{if(state.ws!==ws)return;if(role==='host'&&state.hostCode){state.hostStatus='disconnected';toast('ช่องสัญญาณถูกตัด กรุณาสร้างรหัสจับคู่ใหม่','err');state.hostCode=null;stopStream();render();}else if(role==='viewer'&&state.liveSession){state.connection='ช่องสัญญาณขัดข้อง';render();}};return ws;}
function socketSend(msg){if(state.ws?.readyState===WebSocket.OPEN){state.ws.send(JSON.stringify(msg));return true;}return false;}
async function startHost(){if(!state.backend){toast('ต้องเริ่ม Backend ก่อนจึงแชร์จริงได้ ดู README_TH.md','err');return;}const name=(document.getElementById('host-name')?.value||'Windows ของฉัน').trim().slice(0,80);try{const data=await api('/host/register',{method:'POST',body:JSON.stringify({name})});state.hostName=name;state.rtcConfig=data.rtcConfig||state.rtcConfig;state.hostToken=data.token;state.hostCode=data.code;state.hostRequests=[];state.hostStatus='connecting';state.hostExpiry=data.expiresAt;connectSocket('host',data.token);render();toast('สร้างรหัสจับคู่สำเร็จ');}catch(err){toast(err.message,'err');}}
async function stopHost(){if(state.hostToken){try{await api('/host/revoke',{method:'POST',body:JSON.stringify({token:state.hostToken})});}catch{}}closePeer();stopStream();try{state.ws?.close()}catch{}state.ws=null;state.hostToken=null;state.hostCode=null;state.hostRequests=[];state.hostStatus='idle';render();toast('ยกเลิกการแชร์แล้ว');}
function stopStream(){if(state.localStream){state.localStream.getTracks().forEach(t=>t.stop());state.localStream=null;}closePeer();}
async function acceptHost(sessionId){try{
 if(!navigator.mediaDevices?.getDisplayMedia)throw new Error('ต้องใช้ Chrome/Edge ผ่าน HTTPS หรือ localhost');
 const stream=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:15},audio:false,preferCurrentTab:false,selfBrowserSurface:'exclude'});
 stream.getVideoTracks()[0]?.addEventListener('ended',()=>{socketSend({type:'end',sessionId});stopStream();render();toast('เจ้าของเครื่องหยุดการแชร์ภาพแล้ว');},{once:true});
 state.localStream=stream;state.activeSessionId=sessionId;state.hostRequests=state.hostRequests.filter(r=>r.sessionId!==sessionId);
 socketSend({type:'accept',sessionId});render();attachHostVideo();await createHostPeer(sessionId,stream);toast('เริ่มแชร์ภาพอย่างปลอดภัยแล้ว');
 }catch(err){toast('ไม่ได้เริ่มแชร์: '+err.message,'err');}}
async function createPeer(sessionId,asHost=false){closePeer();const pc=new RTCPeerConnection(state.rtcConfig||{iceServers:[{urls:'stun:stun.l.google.com:19302'}]});state.pc=pc;pc.onicecandidate=event=>{if(event.candidate)socketSend({type:'signal',sessionId,payload:{kind:'candidate',candidate:event.candidate}})};
 pc.onconnectionstatechange=()=>{state.connection=pc.connectionState;if(pc.connectionState==='connected')toast('WebRTC เชื่อมต่อแล้ว');if(pc.connectionState==='failed')toast('WebRTC เชื่อมต่อไม่ได้ อาจต้องมี TURN server','err');};
 pc.ontrack=ev=>{state.remoteStream=ev.streams[0]||new MediaStream([ev.track]);state.connection='connected';attachViewerVideo();};
 pc.ondatachannel=ev=>setupChannel(ev.channel);if(asHost){const channel=pc.createDataChannel('krabak-files',{ordered:true});setupChannel(channel);}return pc;}
async function createHostPeer(sessionId,stream){const pc=await createPeer(sessionId,true);for(const track of stream.getTracks())pc.addTrack(track,stream);const offer=await pc.createOffer();await pc.setLocalDescription(offer);socketSend({type:'signal',sessionId,payload:{kind:'offer',sdp:pc.localDescription}});}
let pendingIce=[];
async function handleSignal(data){const {sessionId,payload}=data;if(!payload||!sessionId)return;try{
 if(payload.kind==='offer'){if(!state.liveSession||state.liveSession.id!==sessionId)return;const pc=await createPeer(sessionId,false);await pc.setRemoteDescription(new RTCSessionDescription(payload.sdp));for(const ice of pendingIce)await pc.addIceCandidate(ice).catch(()=>{});pendingIce=[];const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socketSend({type:'signal',sessionId,payload:{kind:'answer',sdp:pc.localDescription}});state.connection='กำลังรับภาพ';render();}
 else if(payload.kind==='answer'){if(state.pc)await state.pc.setRemoteDescription(new RTCSessionDescription(payload.sdp));}
 else if(payload.kind==='candidate'){if(state.pc?.remoteDescription)await state.pc.addIceCandidate(new RTCIceCandidate(payload.candidate));else pendingIce.push(new RTCIceCandidate(payload.candidate));}
 }catch(err){console.error(err);toast('WebRTC signaling: '+err.message,'err');}}
function attachHostVideo(){const vid=document.getElementById('host-video');if(vid&&state.localStream){vid.srcObject=state.localStream;vid.classList.remove('hidden');vid.play().catch(()=>{});}}
function attachViewerVideo(){const vid=document.getElementById('live-video');if(vid&&state.remoteStream){vid.srcObject=state.remoteStream;vid.classList.remove('hidden');const placeholder=document.getElementById('live-placeholder');if(placeholder)placeholder.classList.add('hidden');vid.play().catch(()=>{});}const stage=document.querySelector('#remote-stage-body .monitor-preview, #remote-stage-body .isolated-app');if(stage)stage.style.transform=`scale(${state.zoom/100})`;}
function closePeer(){if(state.pc){try{state.pc.close()}catch{}state.pc=null}state.rtcChannel=null;state.remoteStream=null;pendingIce=[];}
async function requestSession(ev){ev.preventDefault();const code=document.getElementById('pair-code')?.value.trim().toUpperCase();if(!state.backend){toast('ต้อง Deploy Backend ก่อนจึงจับคู่ได้','err');return;}if(!state.account){toast('กรุณาเข้าสู่ระบบผู้ดูก่อนเชื่อมต่อ','err');state.modal=null;navigate('login');return;}try{const data=await api('/sessions',{method:'POST',body:JSON.stringify({code})});state.rtcConfig=data.rtcConfig||state.rtcConfig;state.liveSession={id:data.id,hostName:data.hostName};state.connection='รอเจ้าของเครื่องอนุญาต';state.hostChat=[];state.files=[];state.modal=null;state.right='chat';state.remoteStream=null;connectSocket('viewer');navigate('remote/live');toast('ส่งคำขอแล้ว กรุณารอให้เจ้าของเครื่องยืนยัน');}catch(err){toast(err.message,'err');}}
function endLive(){if(state.liveSession)socketSend({type:'end',sessionId:state.liveSession.id});closePeer();state.liveSession=null;state.hostChat=[];state.sessionEnded=true;try{state.ws?.close()}catch{}state.ws=null;navigate('devices');toast('สิ้นสุดเซสชันแล้ว');}
function sendChat(text){const safe=text.trim().slice(0,2000);if(!safe)return;if(state.liveSession||state.activeSessionId){let id=state.liveSession?.id||state.activeSessionId;if(!socketSend({type:'chat',sessionId:id,text:safe})){toast('ไม่ได้เชื่อมต่อช่องสัญญาณ','err');return}state.hostChat.push({mine:true,text:safe,time:now()});}
 else state.chat.push({mine:true,text:safe,time:now()});render();}
let receivedFile=null;
function setupChannel(channel){state.rtcChannel=channel;channel.binaryType='arraybuffer';channel.onopen=()=>toast('ช่องส่งไฟล์ WebRTC พร้อมใช้งาน');channel.onmessage=ev=>{
 if(typeof ev.data==='string'){let m;try{m=JSON.parse(ev.data)}catch{return};if(m.type==='file-meta'){if(m.size>8*1024*1024){receivedFile=null;return}receivedFile={name:String(m.name||'file.bin').slice(0,160),size:m.size,chunks:[],received:0};}
 else if(m.type==='file-end'&&receivedFile){const f=receivedFile;receivedFile=null;if(f.received!==f.size){toast('ไฟล์ที่ได้รับไม่ครบ','err');return;}const blob=new Blob(f.chunks);const url=URL.createObjectURL(blob);state.files.unshift({name:f.name,status:'รับแล้ว · คลิกบันทึกไฟล์',url,id:crypto.randomUUID()});toast('ได้รับไฟล์ '+f.name);render();}}
 else if(receivedFile&&ev.data instanceof ArrayBuffer){receivedFile.chunks.push(ev.data);receivedFile.received+=ev.data.byteLength;if(receivedFile.received>8*1024*1024)receivedFile=null;}
 };channel.onclose=()=>{if(state.rtcChannel===channel)state.rtcChannel=null;};}
async function sendFile(file){if(!file)return;if(file.size>8*1024*1024){toast('ไฟล์ทดลองรองรับไม่เกิน 8 MB','err');return;}if(state.liveSession||state.activeSessionId){const ch=state.rtcChannel;if(!ch||ch.readyState!=='open'){toast('ช่องส่งไฟล์ยังไม่พร้อม','err');return;}const id=crypto.randomUUID();state.files.unshift({id,name:file.name,status:'กำลังส่ง...'});render();try{ch.send(JSON.stringify({type:'file-meta',name:file.name,size:file.size}));for(let offset=0;offset<file.size;offset+=12000){const chunk=await file.slice(offset,offset+12000).arrayBuffer();while(ch.bufferedAmount>512*1024)await new Promise(r=>setTimeout(r,25));ch.send(chunk);}ch.send(JSON.stringify({type:'file-end'}));state.files.find(f=>f.id===id).status='ส่งแล้วผ่าน WebRTC';toast('ส่งไฟล์แล้ว ผู้รับต้องเลือกบันทึก');render();}catch(err){toast('ส่งไฟล์ไม่สำเร็จ: '+err.message,'err');}}
 else{state.files.unshift({name:file.name,status:'จำลองการส่ง · ไม่ได้โอนจริง',id:crypto.randomUUID()});toast('เพิ่มไฟล์ในประวัติตัวอย่างแล้ว');render();}}
function sendClipboard(text){const safe=text.slice(0,2000);if(!safe.trim())return;sendChat('[ข้อความจากคลิปบอร์ด]\n'+safe);state.modal=null;render();}
async function onAction(act,el){switch(act){
 case 'mobile-menu':state.mobileMenu=!state.mobileMenu;render();break;
 case 'demo-remote':selectDevice(demoDevices[0].id);break;
 case 'open-device':selectDevice(el.dataset.device);break;
 case 'device-info':showModal('device',{device:demoDevices.find(d=>d.id===el.dataset.device)});break;
 case 'info-remote':{const id=state.modal?.device?.id;state.modal=null;selectDevice(id);break;}
 case 'go-host':navigate('host');break;case 'go-devices':if(state.liveSession)endLive();else navigate('devices');break;
 case 'go-login':navigate('login');break;case 'connect-code':showModal('connect');break;
 case 'close-modal':state.modal=null;render();break;
 case 'grid-view':state.deviceView='grid';render();break;case 'list-view':state.deviceView='list';render();break;
 case 'mode-monitor':state.mode='monitor';state.multi=false;state.zoom=100;render();if(state.liveSession)toast('ผู้แชร์เป็นคนเลือกแหล่งภาพจริงจาก Chrome/Edge');break;
 case 'mode-window':state.mode='window';state.multi=false;state.zoom=100;render();if(state.liveSession)toast('เครื่องปลายทางต้องเลือกหน้าต่างใหม่ด้วยตนเอง');break;
 case 'monitor':state.monitor=Number(el.dataset.idx)||0;state.multi=false;render();break;
 case 'toggle-multi':state.multi=!state.multi;state.mode='monitor';render();break;
 case 'select-app':state.app=el.dataset.app;state.mode='window';state.multi=false;render();break;
 case 'tab-chat':state.right='chat';render();break;case 'tab-files':state.right='files';render();break;case 'tab-info':state.right='info';render();break;
 case 'end-demo':navigate('devices');toast('ปิดเซสชันจำลองแล้ว');break;case 'end-live':endLive();break;
 case 'quality':showModal('quality');break;
 case 'fit':state.zoom=100;state.fit=true;render();break;
 case 'zoom-in':state.zoom=Math.min(150,state.zoom+10);render();break;case 'zoom-out':state.zoom=Math.max(50,state.zoom-10);render();break;
 case 'fullscreen':{const stage=document.getElementById('remote-stage');if(!document.fullscreenElement)await stage?.requestFullscreen?.().catch(()=>toast('เบราว์เซอร์ไม่อนุญาตโหมดเต็มจอ','err'));else await document.exitFullscreen?.();break;}
 case 'clipboard-modal':showModal('clipboard');break;case 'keyboard':showModal('keyboard');break;case 'demo-key':toast(`ชุดคีย์ ${el.dataset.keycombo} เป็นโหมดจำลอง ยังไม่ได้ส่งเข้า Windows`);break;
 case 'send-file':document.getElementById('remote-file')?.click();break;
 case 'host-send-file':document.getElementById('host-file')?.click();break;
 case 'download-file':{const f=state.files.find(x=>x.id===el.dataset.fileId);if(f?.url){const a=document.createElement('a');a.href=f.url;a.download=f.name;a.click();}break;}
 case 'files-help':toast('เปิดเซสชันรีโมตก่อนเพื่อส่งไฟล์จริง');navigate('remote/demo');break;
 case 'start-host':await startHost();break;case 'regenerate-host':await stopHost();await startHost();break;case 'stop-host':await stopHost();break;case 'stop-stream':socketSend({type:'end',sessionId:state.activeSessionId});stopStream();state.activeSessionId=null;render();toast('หยุดแชร์หน้าจอแล้ว');break;
 case 'accept-host':await acceptHost(el.dataset.session);break;
 case 'reject-host':socketSend({type:'reject',sessionId:el.dataset.session});state.hostRequests=state.hostRequests.filter(r=>r.sessionId!==el.dataset.session);render();toast('ปฏิเสธคำขอแล้ว');break;
 case 'copy-host-code':await navigator.clipboard.writeText(state.hostCode||'').then(()=>toast('คัดลอกรหัสแล้ว')).catch(()=>toast('เบราว์เซอร์ไม่อนุญาตคลิปบอร์ด','err'));break;
 case 'request-change':socketSend({type:'change-request',sessionId:state.liveSession?.id});toast('ส่งคำขอแล้ว เจ้าของเครื่องต้องหยุดแชร์และเลือกใหม่');break;
 case 'toggle-setting':{const k=el.dataset.key;state.settings[k]=!state.settings[k];localStorage.setItem('krabak-prefs',JSON.stringify(state.settings));render();break;}
 case 'reset-settings':showModal('confirm-reset');break;
 case 'confirm-reset':{localStorage.removeItem('krabak-prefs');state.settings={theme:'dark',quality:'balanced',clipboard:true,notifications:true,conserve:true,defaultMode:'window'};state.modal=null;render();toast('คืนค่าการตั้งค่าแล้ว');break;}
 case 'save-quality':state.quality=document.getElementById('quality-input')?.value||'balanced';state.zoom=Number(document.getElementById('zoom-range')?.value||100);state.modal=null;render();toast('บันทึกการแสดงผลแล้ว');break;
 case 'help':showModal('help');break;
 case 'install-pwa':if(state.installPrompt){state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;}else showModal('pwa');break;
 case 'refresh-audit':if(state.account)await refreshAudit().catch(err=>toast(err.message,'err'));else toast('กิจกรรมที่แสดงเป็นข้อมูลตัวอย่าง');break;
 case 'demo-mode':state.apiError='';navigate('dashboard');break;case 'logout':await logout();break;
 default:break;
}}
document.addEventListener('click',async ev=>{const nav=ev.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const act=ev.target.closest('[data-act]');if(act){ev.preventDefault();await onAction(act.dataset.act,act);return;}if(ev.target.matches('[data-overlay]')){state.modal=null;render();}});
document.addEventListener('submit',async ev=>{if(ev.target.matches('#login-form')){await login(ev);return}if(ev.target.matches('#pair-form')){await requestSession(ev);return}if(ev.target.matches('#chat-form')){ev.preventDefault();const input=document.getElementById('chat-input');const val=input?.value;input.value='';sendChat(val);return}if(ev.target.matches('#host-chat-form')){ev.preventDefault();const input=document.getElementById('host-chat-input');const val=input?.value;input.value='';sendChat(val);return}if(ev.target.matches('#clipboard-form')){ev.preventDefault();sendClipboard(document.getElementById('clipboard-text')?.value||'');return}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='device-filter'){state.filter=t.value;render();}else if(t.dataset.setting){state.settings[t.dataset.setting]=t.value;localStorage.setItem('krabak-prefs',JSON.stringify(state.settings));render();toast('บันทึกการตั้งค่าแล้ว');}else if(t.id==='remote-file'||t.id==='host-file'){const file=t.files?.[0];if(file)sendFile(file);}});
document.addEventListener('input',ev=>{if(ev.target.id==='device-search'){let pos=ev.target.selectionStart;state.search=ev.target.value;render();const inp=document.getElementById('device-search');inp?.focus();inp?.setSelectionRange(pos,pos);}if(ev.target.id==='zoom-range'){const small=ev.target.parentElement?.querySelector('small');if(small)small.textContent=ev.target.value+'%';}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&state.modal){state.modal=null;render();}if((ev.ctrlKey||ev.metaKey)&&ev.key==='k'&&state.route==='devices'){ev.preventDefault();document.getElementById('device-search')?.focus();}});
let previousRoute=route().split('/')[0];window.addEventListener('hashchange',()=>{const next=route().split('/')[0];if(previousRoute==='host'&&next!=='host'&&(state.hostCode||state.localStream)){stopHost().catch(()=>{});}previousRoute=next;render();});
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();state.installPrompt=ev;});
window.addEventListener('pagehide',()=>{if(state.localStream){state.localStream.getTracks().forEach(t=>t.stop());}});
if('serviceWorker'in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));}
render();checkBackend().catch(()=>{});
